-- Production hospitality core: tenant-scoped property operations, availability, front desk, folios, POS, and guest services.
BEGIN;

CREATE TABLE IF NOT EXISTS public.hospitality_properties (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE,
  branch_id uuid REFERENCES public.branches(id) ON DELETE SET NULL, name text NOT NULL, code text, address text, timezone text NOT NULL DEFAULT 'Africa/Dar_es_Salaam', currency text NOT NULL DEFAULT 'TZS', status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id, name)
);
CREATE TABLE IF NOT EXISTS public.hospitality_amenities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, name text NOT NULL, category text, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS public.hospitality_room_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, name text NOT NULL, code text, capacity_adults integer NOT NULL DEFAULT 2, capacity_children integer NOT NULL DEFAULT 0, base_rate numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', amenities jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(property_id,name));
CREATE TABLE IF NOT EXISTS public.hospitality_rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, room_type_id uuid NOT NULL REFERENCES public.hospitality_room_types(id) ON DELETE RESTRICT, room_number text NOT NULL, floor text, status text NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Reserved','Occupied','Dirty','Cleaning','Inspected','Out of Service','Maintenance')), housekeeping_status text NOT NULL DEFAULT 'Clean', maintenance_status text NOT NULL DEFAULT 'Operational', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(property_id,room_number));
CREATE TABLE IF NOT EXISTS public.hospitality_guests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, first_name text NOT NULL, last_name text NOT NULL, email text, phone text, nationality text, date_of_birth date, loyalty_number text, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,email));
CREATE TABLE IF NOT EXISTS public.hospitality_guest_kyc (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, guest_id uuid NOT NULL REFERENCES public.hospitality_guests(id) ON DELETE CASCADE, document_id uuid REFERENCES public.documents(id) ON DELETE SET NULL, id_type text NOT NULL, id_number text, issuing_country text, expires_at date, verification_status text NOT NULL DEFAULT 'Pending', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_rate_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, room_type_id uuid REFERENCES public.hospitality_room_types(id) ON DELETE CASCADE, name text NOT NULL, currency text NOT NULL DEFAULT 'TZS', nightly_rate numeric(18,2) NOT NULL DEFAULT 0, effective_from date NOT NULL DEFAULT current_date, effective_to date, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, CHECK(effective_to IS NULL OR effective_to >= effective_from));
CREATE TABLE IF NOT EXISTS public.hospitality_taxes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, name text NOT NULL, code text NOT NULL, rate numeric(18,6) NOT NULL DEFAULT 0, applies_to text NOT NULL DEFAULT 'Folio', effective_from date NOT NULL DEFAULT current_date, effective_to date, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(company_id,code,effective_from));
CREATE TABLE IF NOT EXISTS public.hospitality_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, guest_id uuid NOT NULL REFERENCES public.hospitality_guests(id) ON DELETE RESTRICT, room_type_id uuid REFERENCES public.hospitality_room_types(id) ON DELETE RESTRICT, room_id uuid REFERENCES public.hospitality_rooms(id) ON DELETE RESTRICT, confirmation_code text NOT NULL, arrival_date date NOT NULL, departure_date date NOT NULL, adults integer NOT NULL DEFAULT 1, children integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Confirmed','Checked In','Checked Out','Cancelled','No Show')), nightly_rate numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', source text NOT NULL DEFAULT 'Front Desk', special_requests text, checked_in_at timestamptz, checked_out_at timestamptz, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(departure_date > arrival_date), UNIQUE(company_id,confirmation_code));
CREATE INDEX IF NOT EXISTS hospitality_reservations_room_window_idx ON public.hospitality_reservations(company_id,room_id,arrival_date,departure_date);
CREATE TABLE IF NOT EXISTS public.hospitality_folios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, reservation_id uuid UNIQUE REFERENCES public.hospitality_reservations(id) ON DELETE CASCADE, guest_id uuid NOT NULL REFERENCES public.hospitality_guests(id) ON DELETE RESTRICT, folio_number text NOT NULL, status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Closed','Voided')), currency text NOT NULL DEFAULT 'TZS', finance_reference text, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,folio_number));
CREATE TABLE IF NOT EXISTS public.hospitality_folio_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, folio_id uuid NOT NULL REFERENCES public.hospitality_folios(id) ON DELETE CASCADE, line_type text NOT NULL CHECK(line_type IN ('Room','Dining','Minibar','Laundry','Event','Tax','Discount','Deposit','Payment','Refund','Adjustment')), description text NOT NULL, quantity numeric(18,3) NOT NULL DEFAULT 1, unit_amount numeric(18,2) NOT NULL DEFAULT 0, amount numeric(18,2) NOT NULL DEFAULT 0, tax_amount numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', source_table text, source_record_id uuid, posted_by uuid DEFAULT auth.uid(), posted_at timestamptz NOT NULL DEFAULT now(), data jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.hospitality_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, folio_id uuid NOT NULL REFERENCES public.hospitality_folios(id) ON DELETE RESTRICT, payment_method text NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount > 0), currency text NOT NULL DEFAULT 'TZS', status text NOT NULL DEFAULT 'Captured', reference text, finance_payment_id uuid, received_by uuid DEFAULT auth.uid(), received_at timestamptz NOT NULL DEFAULT now(), data jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.hospitality_housekeeping_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.hospitality_rooms(id) ON DELETE CASCADE, assigned_employee_id uuid REFERENCES public.hr_employees(id) ON DELETE SET NULL, task_type text NOT NULL DEFAULT 'Checkout Clean', status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Assigned','In Progress','Completed','Inspected')), due_at timestamptz, completed_at timestamptz, notes text, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_maintenance_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, room_id uuid REFERENCES public.hospitality_rooms(id) ON DELETE SET NULL, category text NOT NULL, priority text NOT NULL DEFAULT 'Normal', status text NOT NULL DEFAULT 'Open', assigned_employee_id uuid REFERENCES public.hr_employees(id) ON DELETE SET NULL, notes text, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_restaurant_tables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, table_number text NOT NULL, capacity integer NOT NULL DEFAULT 2, zone text, status text NOT NULL DEFAULT 'Available', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(property_id,table_number));
CREATE TABLE IF NOT EXISTS public.hospitality_menus (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, name text NOT NULL, meal_period text, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.hospitality_menu_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, menu_id uuid NOT NULL REFERENCES public.hospitality_menus(id) ON DELETE CASCADE, inventory_item_id uuid REFERENCES public.inventory_items(id) ON DELETE SET NULL, name text NOT NULL, price numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.hospitality_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, table_id uuid REFERENCES public.hospitality_restaurant_tables(id) ON DELETE SET NULL, reservation_id uuid REFERENCES public.hospitality_reservations(id) ON DELETE SET NULL, folio_id uuid REFERENCES public.hospitality_folios(id) ON DELETE SET NULL, order_number text NOT NULL, status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Sent','Preparing','Ready','Served','Paid','Cancelled')), currency text NOT NULL DEFAULT 'TZS', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,order_number));
CREATE TABLE IF NOT EXISTS public.hospitality_order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.hospitality_orders(id) ON DELETE CASCADE, menu_item_id uuid REFERENCES public.hospitality_menu_items(id) ON DELETE SET NULL, name text NOT NULL, quantity numeric(18,3) NOT NULL DEFAULT 1, unit_price numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'New', data jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.hospitality_minibar_postings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, reservation_id uuid NOT NULL REFERENCES public.hospitality_reservations(id) ON DELETE CASCADE, inventory_item_id uuid REFERENCES public.inventory_items(id) ON DELETE SET NULL, quantity numeric(18,3) NOT NULL DEFAULT 1, amount numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Posted', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_laundry_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, reservation_id uuid REFERENCES public.hospitality_reservations(id) ON DELETE SET NULL, guest_id uuid REFERENCES public.hospitality_guests(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'Received', amount numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_event_venues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, name text NOT NULL, capacity integer NOT NULL DEFAULT 0, base_rate numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(property_id,name));
CREATE TABLE IF NOT EXISTS public.hospitality_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.hospitality_properties(id) ON DELETE CASCADE, venue_id uuid REFERENCES public.hospitality_event_venues(id) ON DELETE SET NULL, guest_id uuid REFERENCES public.hospitality_guests(id) ON DELETE SET NULL, name text NOT NULL, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'Enquiry', amount numeric(18,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'TZS', data jsonb NOT NULL DEFAULT '{}'::jsonb, CHECK(end_at > start_at));
CREATE TABLE IF NOT EXISTS public.hospitality_guest_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, reservation_id uuid REFERENCES public.hospitality_reservations(id) ON DELETE SET NULL, guest_id uuid REFERENCES public.hospitality_guests(id) ON DELETE SET NULL, request_type text NOT NULL, description text NOT NULL, priority text NOT NULL DEFAULT 'Normal', status text NOT NULL DEFAULT 'Open', assigned_employee_id uuid REFERENCES public.hr_employees(id) ON DELETE SET NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_complaints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, reservation_id uuid REFERENCES public.hospitality_reservations(id) ON DELETE SET NULL, guest_id uuid REFERENCES public.hospitality_guests(id) ON DELETE SET NULL, category text, description text NOT NULL, status text NOT NULL DEFAULT 'Open', resolution text, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_loyalty_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, guest_id uuid NOT NULL REFERENCES public.hospitality_guests(id) ON DELETE CASCADE, tier text NOT NULL DEFAULT 'Member', points numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Active', data jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(company_id,guest_id));
CREATE TABLE IF NOT EXISTS public.hospitality_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, profile_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, employee_id uuid REFERENCES public.hr_employees(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, type text NOT NULL DEFAULT 'Hospitality', module text NOT NULL DEFAULT 'hospitality', record_id uuid, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hospitality_audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT current_company_id() REFERENCES public.companies(id) ON DELETE CASCADE, actor_profile_id uuid DEFAULT auth.uid(), action text NOT NULL, subject text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION public.hospitality_is_privileged() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT lower(role) IN ('owner','admin','manager','hotel_manager','front_desk_manager','finance_manager') FROM public.profiles WHERE id=auth.uid()),false) $$;
CREATE OR REPLACE FUNCTION public.hospitality_audit(p_action text,p_subject text,p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.hospitality_audit_log(company_id,action,subject,detail) VALUES(public.current_company_id(),p_action,p_subject,coalesce(p_detail,'{}'::jsonb)); END; $$;
CREATE OR REPLACE FUNCTION public.hospitality_notify(p_employee_id uuid,p_title text,p_body text,p_record_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.hospitality_notifications(company_id,employee_id,profile_id,title,body,record_id) SELECT public.current_company_id(),e.id,e.profile_id,p_title,p_body,p_record_id FROM public.hr_employees e WHERE e.id=p_employee_id; END; $$;

CREATE OR REPLACE FUNCTION public.hospitality_check_room_available(p_room_id uuid,p_arrival date,p_departure date,p_ignore_reservation uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.hospitality_reservations r WHERE r.company_id=public.current_company_id() AND r.room_id=p_room_id AND r.status IN ('Confirmed','Checked In') AND r.arrival_date < p_departure AND r.departure_date > p_arrival AND (p_ignore_reservation IS NULL OR r.id<>p_ignore_reservation)) $$;
CREATE OR REPLACE FUNCTION public.hospitality_snapshot() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_profile uuid:=auth.uid(); BEGIN IF v_profile IS NULL THEN RAISE EXCEPTION 'An authenticated hospitality session is required.' USING ERRCODE='28000'; END IF; RETURN jsonb_build_object('viewer',jsonb_build_object('profileId',v_profile,'isPrivileged',public.hospitality_is_privileged()),'properties',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.hospitality_properties x WHERE x.company_id=public.current_company_id()),'[]'::jsonb),'roomTypes',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.name) FROM public.hospitality_room_types x WHERE x.company_id=public.current_company_id()),'[]'::jsonb),'rooms',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.room_number) FROM public.hospitality_rooms x WHERE x.company_id=public.current_company_id()),'[]'::jsonb),'guests',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.hospitality_guests x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'reservations',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.arrival_date) FROM public.hospitality_reservations x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'folios',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.hospitality_folios x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'housekeeping',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.hospitality_housekeeping_tasks x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'orders',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.hospitality_orders x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'events',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.start_at) FROM public.hospitality_events x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'requests',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.hospitality_guest_requests x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'complaints',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.hospitality_complaints x WHERE x.company_id=public.current_company_id() LIMIT 100),'[]'::jsonb),'notifications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC) FROM public.hospitality_notifications x WHERE x.company_id=public.current_company_id() AND (public.hospitality_is_privileged() OR x.profile_id=v_profile) LIMIT 100),'[]'::jsonb)); END $$;

CREATE OR REPLACE FUNCTION public.hospitality_action(p_action text,p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_property uuid; v_guest uuid; v_room uuid; v_res uuid; v_folio uuid; v_status text; v_amount numeric; v_arrival date; v_departure date; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'An authenticated hospitality session is required.' USING ERRCODE='28000'; END IF; IF NOT public.hospitality_is_privileged() THEN RAISE EXCEPTION 'You are not authorised for this hospitality operation.' USING ERRCODE='42501'; END IF;
IF p_action='property.save' THEN INSERT INTO public.hospitality_properties(company_id,branch_id,name,code,address,timezone,currency,data) VALUES(public.current_company_id(),nullif(p_payload->>'branchId','')::uuid,coalesce(p_payload->>'name','Property'),p_payload->>'code',p_payload->>'address',coalesce(p_payload->>'timezone','Africa/Dar_es_Salaam'),coalesce(p_payload->>'currency','TZS'),coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='room_type.save' THEN INSERT INTO public.hospitality_room_types(company_id,property_id,name,code,capacity_adults,capacity_children,base_rate,currency,amenities,data) VALUES(public.current_company_id(),(p_payload->>'propertyId')::uuid,coalesce(p_payload->>'name','Room Type'),p_payload->>'code',coalesce((p_payload->>'adults')::integer,2),coalesce((p_payload->>'children')::integer,0),coalesce((p_payload->>'baseRate')::numeric,0),coalesce(p_payload->>'currency','TZS'),coalesce(p_payload->'amenities','[]'::jsonb),coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='room.save' THEN INSERT INTO public.hospitality_rooms(company_id,property_id,room_type_id,room_number,floor,data) VALUES(public.current_company_id(),(p_payload->>'propertyId')::uuid,(p_payload->>'roomTypeId')::uuid,coalesce(p_payload->>'roomNumber','Room'),p_payload->>'floor',coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='guest.save' THEN INSERT INTO public.hospitality_guests(company_id,first_name,last_name,email,phone,nationality,data) VALUES(public.current_company_id(),coalesce(p_payload->>'firstName','Guest'),coalesce(p_payload->>'lastName',''),nullif(p_payload->>'email',''),p_payload->>'phone',p_payload->>'nationality',coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='reservation.create' THEN v_property:=(p_payload->>'propertyId')::uuid; v_guest:=(p_payload->>'guestId')::uuid; v_room:=nullif(p_payload->>'roomId','')::uuid; v_arrival:=(p_payload->>'arrivalDate')::date; v_departure:=(p_payload->>'departureDate')::date; IF v_arrival IS NULL OR v_departure IS NULL OR v_departure<=v_arrival THEN RAISE EXCEPTION 'A valid arrival and departure date are required.' USING ERRCODE='22007'; END IF; IF v_room IS NOT NULL AND NOT public.hospitality_check_room_available(v_room,v_arrival,v_departure,NULL) THEN RAISE EXCEPTION 'The selected room is not available for this stay.' USING ERRCODE='23P01'; END IF; INSERT INTO public.hospitality_reservations(company_id,property_id,guest_id,room_type_id,room_id,confirmation_code,arrival_date,departure_date,adults,children,status,nightly_rate,currency,source,special_requests,data) VALUES(public.current_company_id(),v_property,v_guest,nullif(p_payload->>'roomTypeId','')::uuid,v_room,coalesce(p_payload->>'confirmationCode','RES-'||substr(gen_random_uuid()::text,1,8)),v_arrival,v_departure,coalesce((p_payload->>'adults')::integer,1),coalesce((p_payload->>'children')::integer,0),'Confirmed',coalesce((p_payload->>'nightlyRate')::numeric,0),coalesce(p_payload->>'currency','TZS'),coalesce(p_payload->>'source','Front Desk'),p_payload->>'specialRequests',coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='reservation.check_in' THEN v_res:=(p_payload->>'reservationId')::uuid; SELECT property_id,guest_id,room_id,status INTO v_property,v_guest,v_room,v_status FROM public.hospitality_reservations WHERE id=v_res AND company_id=public.current_company_id(); IF v_res IS NULL OR v_status NOT IN ('Confirmed','Draft') THEN RAISE EXCEPTION 'Only a confirmed reservation can be checked in.' USING ERRCODE='55000'; END IF; IF v_room IS NULL THEN RAISE EXCEPTION 'Assign an available room before check-in.' USING ERRCODE='P0002'; END IF; IF NOT public.hospitality_check_room_available(v_room,current_date,(SELECT departure_date FROM public.hospitality_reservations WHERE id=v_res),v_res) THEN RAISE EXCEPTION 'The assigned room is no longer available.' USING ERRCODE='23P01'; END IF; UPDATE public.hospitality_reservations SET status='Checked In',checked_in_at=now(),updated_at=now() WHERE id=v_res; UPDATE public.hospitality_rooms SET status='Occupied',updated_at=now() WHERE id=v_room; INSERT INTO public.hospitality_folios(company_id,property_id,reservation_id,guest_id,folio_number,currency) VALUES(public.current_company_id(),v_property,v_res,v_guest,'FOL-'||substr(gen_random_uuid()::text,1,8),coalesce(p_payload->>'currency','TZS')) RETURNING id INTO v_id;
ELSIF p_action='folio.post_charge' THEN v_folio:=(p_payload->>'folioId')::uuid; SELECT id INTO v_id FROM public.hospitality_folios WHERE id=v_folio AND company_id=public.current_company_id() AND status='Open'; IF v_id IS NULL THEN RAISE EXCEPTION 'An open folio is required.' USING ERRCODE='P0002'; END IF; v_amount:=coalesce((p_payload->>'amount')::numeric,0); INSERT INTO public.hospitality_folio_lines(company_id,folio_id,line_type,description,quantity,unit_amount,amount,tax_amount,currency,source_table,source_record_id,data) VALUES(public.current_company_id(),v_folio,coalesce(p_payload->>'lineType','Adjustment'),coalesce(p_payload->>'description','Hospitality charge'),coalesce((p_payload->>'quantity')::numeric,1),v_amount,v_amount*coalesce((p_payload->>'quantity')::numeric,1),coalesce((p_payload->>'taxAmount')::numeric,0),coalesce(p_payload->>'currency','TZS'),p_payload->>'sourceTable',nullif(p_payload->>'sourceRecordId','')::uuid,coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSIF p_action='payment.record' THEN v_folio:=(p_payload->>'folioId')::uuid; v_amount:=coalesce((p_payload->>'amount')::numeric,0); IF v_amount<=0 THEN RAISE EXCEPTION 'Payment amount must be greater than zero.' USING ERRCODE='22023'; END IF; INSERT INTO public.hospitality_payments(company_id,folio_id,payment_method,amount,currency,reference,data) VALUES(public.current_company_id(),v_folio,coalesce(p_payload->>'method','Cash'),v_amount,coalesce(p_payload->>'currency','TZS'),p_payload->>'reference',coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id; INSERT INTO public.hospitality_folio_lines(company_id,folio_id,line_type,description,quantity,unit_amount,amount,currency,source_table,source_record_id) VALUES(public.current_company_id(),v_folio,'Payment','Payment received',1,-v_amount,-v_amount,coalesce(p_payload->>'currency','TZS'),'hospitality_payments',v_id);
ELSIF p_action='reservation.check_out' THEN v_res:=(p_payload->>'reservationId')::uuid; SELECT r.room_id,r.status,f.id INTO v_room,v_status,v_folio FROM public.hospitality_reservations r JOIN public.hospitality_folios f ON f.reservation_id=r.id WHERE r.id=v_res AND r.company_id=public.current_company_id(); IF v_status<>'Checked In' THEN RAISE EXCEPTION 'Only a checked-in reservation can be checked out.' USING ERRCODE='55000'; END IF; IF coalesce((SELECT sum(amount+tax_amount) FROM public.hospitality_folio_lines WHERE folio_id=v_folio),0) <> 0 AND coalesce((p_payload->>'allowOutstanding')::boolean,false)=false THEN RAISE EXCEPTION 'Folio has an outstanding balance. Record payment or explicitly allow outstanding.' USING ERRCODE='55000'; END IF; UPDATE public.hospitality_reservations SET status='Checked Out',checked_out_at=now(),updated_at=now() WHERE id=v_res; UPDATE public.hospitality_folios SET status='Closed',updated_at=now() WHERE id=v_folio; UPDATE public.hospitality_rooms SET status='Dirty',housekeeping_status='Dirty',updated_at=now() WHERE id=v_room; INSERT INTO public.hospitality_housekeeping_tasks(company_id,property_id,room_id,task_type,status,due_at) SELECT public.current_company_id(),property_id,v_room,'Checkout Clean','Open',now() FROM public.hospitality_reservations WHERE id=v_res RETURNING id INTO v_id;
ELSIF p_action='housekeeping.complete' THEN v_id:=(p_payload->>'taskId')::uuid; SELECT room_id INTO v_room FROM public.hospitality_housekeeping_tasks WHERE id=v_id AND company_id=public.current_company_id(); UPDATE public.hospitality_housekeeping_tasks SET status='Completed',completed_at=now(),updated_at=now() WHERE id=v_id; UPDATE public.hospitality_rooms SET status='Available',housekeeping_status='Clean',updated_at=now() WHERE id=v_room;
ELSIF p_action='guest_request.create' THEN INSERT INTO public.hospitality_guest_requests(company_id,reservation_id,guest_id,request_type,description,priority,data) VALUES(public.current_company_id(),nullif(p_payload->>'reservationId','')::uuid,nullif(p_payload->>'guestId','')::uuid,coalesce(p_payload->>'requestType','Guest Service'),coalesce(p_payload->>'description',''),coalesce(p_payload->>'priority','Normal'),coalesce(p_payload->'data','{}'::jsonb)) RETURNING id INTO v_id;
ELSE RAISE EXCEPTION 'Unsupported hospitality action: %',p_action USING ERRCODE='22023'; END IF; PERFORM public.hospitality_audit(upper(replace(p_action,'.','_')),coalesce(v_id::text,p_action),p_payload); RETURN jsonb_build_object('ok',true,'action',p_action,'recordId',v_id,'snapshotRequired',true); END $$;

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['hospitality_properties','hospitality_amenities','hospitality_room_types','hospitality_rooms','hospitality_guests','hospitality_guest_kyc','hospitality_rate_plans','hospitality_taxes','hospitality_reservations','hospitality_folios','hospitality_folio_lines','hospitality_payments','hospitality_housekeeping_tasks','hospitality_maintenance_requests','hospitality_restaurant_tables','hospitality_menus','hospitality_menu_items','hospitality_orders','hospitality_order_lines','hospitality_minibar_postings','hospitality_laundry_orders','hospitality_event_venues','hospitality_events','hospitality_guest_requests','hospitality_complaints','hospitality_loyalty_accounts','hospitality_notifications','hospitality_audit_log'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_tenant_select',t); EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',t||'_tenant_write',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (company_id=public.current_company_id())',t||'_tenant_select',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (company_id=public.current_company_id() AND public.hospitality_is_privileged()) WITH CHECK (company_id=public.current_company_id() AND public.hospitality_is_privileged())',t||'_tenant_write',t); END LOOP; END $$;
REVOKE EXECUTE ON FUNCTION public.hospitality_is_privileged() FROM PUBLIC,anon;
REVOKE EXECUTE ON FUNCTION public.hospitality_audit(text,text,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.hospitality_notify(uuid,text,text,uuid) FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.hospitality_check_room_available(uuid,date,date,uuid) FROM PUBLIC,anon;
REVOKE EXECUTE ON FUNCTION public.hospitality_snapshot() FROM PUBLIC,anon;
REVOKE EXECUTE ON FUNCTION public.hospitality_action(text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.hospitality_snapshot() TO authenticated;
GRANT EXECUTE ON FUNCTION public.hospitality_action(text,jsonb) TO authenticated;
COMMIT;
